curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "limit=1000&types=public_channel,private_channel" | python3 -c "
import json,sys
data = json.load(sys.stdin)
targets = []
for c in data.get('channels',[]):
    if not c.get('is_archived'):
        if 'incident' in c.get('name','').lower():
            topic = (c.get('topic',{}).get('value','') or '').lower()
            if 'postmortem' in topic:
                targets.append(c)
                print('MATCH', c['id'], '|', c['name'])
print('count', len(targets))
"
